<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {request} from '../api'
import {projectUsageTrack} from '../usage-track.mjs'
import type {UsageDashboard} from '../usage-dashboard'
import type {ObservabilitySummary,ObservabilityItem} from '../conversation-observability'
import {numberText,rateText,costLines,timeText} from '../observability-format.mjs'
import UsageSummary from './UsageSummary.vue'
import ConversationObservability from './ConversationObservability.vue'
const props=defineProps<{conversationId:string;active:boolean;revision?:unknown;summary?:ObservabilitySummary;items:ObservabilityItem[];loading?:boolean;hasMore?:boolean;showTurnUsage?:boolean}>()
const emit=defineEmits<{round:[string];more:[];'update:showTurnUsage':[boolean]}>()
const roundLimit=ref(50),range=ref('all'),view=ref('overview'),metric=ref('tokens'),data=ref<UsageDashboard|null>(null),loading=ref(false),error=ref(''),selectedBucket=ref(''),inspected=ref<ObservabilityItem|null>(null)
let generation=0,abort:AbortController|undefined
async function refresh(){const ticket=++generation;abort?.abort();data.value=null;error.value='';selectedBucket.value='';if(!props.active){loading.value=false;return}abort=new AbortController();loading.value=true;try{const result=await request<UsageDashboard>(`/developer/conversations/${encodeURIComponent(props.conversationId)}/usage?range=${range.value}`,undefined,'GET',false,abort.signal);if(ticket===generation)data.value=result}catch(cause){if(ticket===generation&&!abort?.signal.aborted)error.value='读取消耗失败，请重试'}finally{if(ticket===generation)loading.value=false}}
watch(()=>[props.active,props.conversationId,range.value,props.revision],()=>{inspected.value=null;void refresh()},{immediate:true})
watch(()=>props.conversationId,()=>{range.value='all';view.value='overview'})
onBeforeUnmount(()=>{generation++;abort?.abort()})
const summary=computed(()=>data.value?{...props.summary,conversationId:props.conversationId,worker:data.value.worker,runtime:data.value.runtime,rounds:[]} as ObservabilitySummary:undefined)
const currencies=computed(()=>data.value?.total.cost.byCurrency.map(row=>row.currency)??[])
watch(currencies,value=>{if(metric.value.startsWith('cost:')&&!value.includes(metric.value.slice(5)))metric.value='tokens'})
function value(bucket:UsageDashboard['buckets'][number]){if(metric.value==='requests')return bucket.requests;if(metric.value==='tokens')return bucket.total.usage.total;const row=bucket.total.cost.byCurrency.find(row=>row.currency===metric.value.slice(5));return row?.amount??row?.knownSubtotal??null}
function bucketLabel(bucket:UsageDashboard['buckets'][number]){const partial=metric.value.startsWith('cost:')&&bucket.total.cost.byCurrency.find(row=>row.currency===metric.value.slice(5))?.amount==null;return `${bucket.label} · ${value(bucket)==null?'—':numberText(value(bucket))}${partial&&value(bucket)!=null?' · 部分估算':''}`}
const max=computed(()=>Math.max(0,...(data.value?.buckets??[]).map(bucket=>value(bucket)??0)))
const visibleRounds=computed(()=>data.value?.rounds.slice(0,roundLimit.value)??[])
watch(range,()=>roundLimit.value=50)
const focused=computed(()=>data.value?.buckets.find(bucket=>bucket.key===selectedBucket.value))
const track=computed(()=>projectUsageTrack(props.items))
const lanes=[{id:'client-function',label:'Client 功能'},{id:'client-worker',label:'Worker'},{id:'runtime-loop',label:'Runtime'}]
function duration(item:ObservabilityItem){return item.status==='running'?'运行中':item.timing?.totalMs==null?'—':`${numberText(item.timing.totalMs)} ms`}
function timestamp(value:string){return new Date(value).toLocaleString('zh-CN',{timeZone:data.value?.timeZone??'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false})}
</script>
<template>
<section class="usage-dashboard" aria-label="对话消耗看板" :aria-busy="loading">
 <header class="usage-head"><h3>对话消耗</h3><button type="button" class="text-button" :disabled="loading||!active" @click="refresh">{{loading?'读取中…':'刷新'}}</button></header>
 <div class="range-switch" role="group" aria-label="统计时间范围"><button v-for="entry in [{id:'today',label:'今天'},{id:'7d',label:'7 天'},{id:'30d',label:'30 天'},{id:'all',label:'全部'}]" :key="entry.id" :aria-pressed="range===entry.id" @click="range=entry.id">{{entry.label}}</button></div>
 <p class="range-context">{{data?`${data.startDay} — ${data.endDay} · ${data.timeZone}`:'正在读取统计范围…'}}</p>
 <p v-if="error" class="usage-error" role="alert">{{error}} <button class="text-button" @click="refresh">重试</button></p>
 <dl class="usage-kpis"><div><dt>总 token</dt><dd>{{numberText(data?.total.usage.total)}}</dd><small v-if="data?.total.usageCoverage.partial||data?.total.usageCoverage.unknown">部分记录</small></div><div><dt>模型请求</dt><dd>{{numberText(data?.requests)}}</dd><small>失败 {{numberText(data?.failed)}} · 取消 {{numberText(data?.cancelled)}}</small></div><div><dt>API 参考估算</dt><dd v-for="line in costLines(data?.total)" :key="line">{{line}}</dd></div><div><dt>输入缓存率</dt><dd>{{rateText(data?.total.usage.cacheRate)}}</dd></div></dl>
 <UsageSummary title="所选时段 · Worker / Runtime" :summary="summary" :loading="loading" :show-turn-usage="showTurnUsage" @update:show-turn-usage="emit('update:showTurnUsage',$event)"/>
 <nav class="dashboard-views" aria-label="消耗查看方式"><button v-for="entry in [{id:'overview',label:'概览'},{id:'rounds',label:'多轮'},{id:'track',label:'轨道'}]" :key="entry.id" :aria-pressed="view===entry.id" @click="view=entry.id">{{entry.label}}</button></nav>
 <template v-if="view==='overview'">
  <div class="chart-metrics" role="group" aria-label="趋势指标"><button :aria-pressed="metric==='tokens'" @click="metric='tokens'">Token</button><button :aria-pressed="metric==='requests'" @click="metric='requests'">请求</button><button v-for="currency in currencies" :key="currency" :aria-pressed="metric===`cost:${currency}`" @click="metric=`cost:${currency}`">费用 · {{currency}}</button></div>
  <div class="usage-chart" aria-label="时段消耗趋势"><span class="chart-max">{{numberText(data?.buckets.some(bucket=>value(bucket)!=null)?max:null)}}</span><div class="chart-bars"><button v-for="bucket in data?.buckets??[]" :key="bucket.key" :aria-label="bucketLabel(bucket)" :aria-pressed="selectedBucket===bucket.key" :title="bucketLabel(bucket)" @click="selectedBucket=bucket.key"><span v-if="value(bucket)!=null" :style="{height:`${max?100*(value(bucket)??0)/max:0}%`}"/></button></div><div class="chart-axis"><span>{{data?.buckets[0]?.label??'—'}}</span><span>{{data?.buckets.at(-1)?.label??'—'}}</span></div></div>
  <p v-if="focused" class="bucket-detail">{{focused.key}} · {{numberText(focused.requests)}} 次请求 · {{numberText(focused.total.usage.total)}} token · {{costLines(focused.total).join(' / ')}}</p>
  <p v-if="data&&!data.requests" class="usage-empty">此时段暂无模型调用</p>
 </template>
 <section v-else-if="view==='rounds'" aria-label="多轮消耗对比" class="round-comparison"><p v-if="data&&!data.rounds.length" class="usage-empty">此时段暂无轮次记录</p><button v-for="round in visibleRounds" :key="round.roundId??'unassigned'" class="usage-round" @click="emit('round',round.roundId?`round:${round.roundId}`:'unassigned');view='track'"><header :title="round.roundId??undefined"><strong>{{round.roundId?'对话轮次':'未归属轮次'}}</strong><time>{{timestamp(round.startedAt)}}</time></header><div v-for="[label,group] in [['Worker',round.worker],['Runtime',round.runtime]] as const" :key="label" class="round-source"><span>{{label}}</span><span>{{numberText(group.usage.total)}} token</span><span>{{rateText(group.usage.cacheRate)}}</span><span>{{costLines(group).join(' / ')}}</span></div><small>{{round.records}} 条记录 · {{round.requests}} 次模型请求 · {{round.failed}} 次失败</small></button><p class="track-context">显示 {{visibleRounds.length}} / {{data?.rounds.length??0}} 轮</p><button v-if="data&&roundLimit<data.rounds.length" class="text-button" @click="roundLimit+=50">加载更多轮次</button></section>
 <section v-else class="usage-trajectory" aria-label="当前轮次执行轨道"><p class="track-context">当前轮次与来源 · 已加载 {{items.length}} 条记录</p><div v-if="track.first!=null" class="track-axis"><time>{{timeText(track.first)}}</time><time>{{timeText(track.last)}}</time></div><div v-for="lane in lanes" :key="lane.id" class="usage-lane"><h4>{{lane.label}}</h4><p v-if="!items.some(item=>item.category===lane.id)" class="usage-empty">暂无记录</p><button v-for="item in [...items].filter(item=>item.category===lane.id).sort((a,b)=>a.sequence-b.sequence)" :key="item.id" :aria-pressed="inspected?.id===item.id" class="track-event" @click="inspected=item"><span class="track-scale" aria-hidden="true"><i :class="{point:track.events.find(event=>event.item.id===item.id)?.width==null}" :style="{left:`min(calc(100% - 2px), ${track.events.find(event=>event.item.id===item.id)?.left??0}%)`,width:track.events.find(event=>event.item.id===item.id)?.width==null?undefined:`${track.events.find(event=>event.item.id===item.id)?.width}%`}"/></span><time>{{timeText(item.time)}}</time><strong>{{item.stage||item.name||item.kind}}</strong><span>{{duration(item)}}</span><small v-if="item.runId">{{item.runId}}</small></button></div><button v-if="hasMore" class="text-button" :disabled="loading||props.loading" @click="emit('more')">加载更早轨道</button><ConversationObservability v-if="inspected" :items="[inspected]"/></section>
</section>
</template>
<style scoped>
.usage-dashboard{min-width:0;font-size:13px;line-height:20px;container-type:inline-size}.usage-head{display:flex;align-items:center;justify-content:space-between;padding:12px 16px 8px}.usage-head h3{font-size:14px;font-weight:500;margin:0}.range-switch,.dashboard-views,.chart-metrics{display:flex;flex-wrap:wrap;gap:4px;padding:0 16px}.range-switch button,.dashboard-views button,.chart-metrics button{font:inherit;padding:4px 8px;min-height:28px;border-radius:6px;color:var(--muted)}button[aria-pressed=true]{background:var(--selected);color:var(--text)}button:hover{background:var(--hover)}.range-context,.track-context{font-size:11px;line-height:16px;color:var(--muted);margin:8px 16px;overflow-wrap:anywhere}.usage-kpis{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));margin:12px 16px;gap:16px 12px}.usage-kpis>div{min-width:0}.usage-kpis dt{font-size:11px;line-height:16px;color:var(--muted)}.usage-kpis dd{margin:4px 0 0;font-size:17px;line-height:24px;font-weight:500;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.usage-kpis small{font-size:11px;color:var(--muted)}.usage-kpis>div:nth-child(3) dd{font-size:13px;line-height:20px}.dashboard-views{padding-block:12px}.chart-metrics{font-size:12px}.usage-chart{margin:12px 16px;position:relative}.chart-max{display:block;font-size:11px;color:var(--muted)}.chart-bars{display:flex;align-items:stretch;height:112px;gap:4px;border-bottom:.5px solid var(--faint)}.chart-bars button{flex:1;min-width:0;display:flex;align-items:flex-end;padding:0;border-radius:0}.chart-bars button>span{display:block;width:100%;background:var(--accent);min-height:0;border-radius:0}.chart-bars button[aria-pressed=true]{background:var(--selected)}.chart-axis{display:flex;justify-content:space-between;font-size:11px;color:var(--muted);margin-top:4px}.usage-error,.usage-empty,.bucket-detail{margin:12px 16px;font-size:12px;line-height:18px;overflow-wrap:anywhere}.usage-error{color:var(--error)}.usage-empty{color:var(--muted)}.round-comparison,.usage-trajectory{min-width:0}.usage-round{display:block;width:calc(100% - 32px);margin:0 16px;padding:12px 0;text-align:left;border-top:.5px solid var(--faint);font:inherit}.usage-round header{display:flex;flex-wrap:wrap;gap:4px 8px;justify-content:space-between}.usage-round header strong{font-weight:500}.usage-round time,.usage-round small{font-size:11px;color:var(--muted)}.round-source{display:grid;grid-template-columns:52px minmax(0,1fr);gap:4px 8px;margin:8px 0;font-size:12px;font-variant-numeric:tabular-nums}.round-source>span:last-child{grid-column:2;overflow-wrap:anywhere}.usage-lane{margin:12px 16px}.usage-lane h4{font-size:12px;font-weight:500;margin:0 0 8px}.track-event{display:grid;grid-template-columns:64px minmax(0,1fr);width:100%;font:inherit;text-align:left;gap:4px 8px;padding:8px;border-radius:6px;border-top:.5px solid var(--faint)}.track-event time,.track-event small{font-size:11px;color:var(--muted)}.track-event strong{font-weight:420;overflow-wrap:anywhere}.track-event small{grid-column:1/-1;overflow-wrap:anywhere}.track-axis{display:flex;justify-content:space-between;margin:8px 16px;font-size:11px;color:var(--muted)}.track-event .track-scale{grid-column:1/-1;position:relative;height:8px;background:var(--hover);overflow:hidden}.track-scale i{display:block;position:absolute;height:100%;min-width:1px;background:var(--accent)}.track-scale i.point{width:2px}.track-event>span:not(.track-scale){grid-column:2;font-size:12px;color:var(--muted)}@container(max-width:220px){.usage-kpis{grid-template-columns:minmax(0,1fr)}.track-event{grid-template-columns:minmax(0,1fr)}.track-event>span{grid-column:1}.round-source{grid-template-columns:minmax(0,1fr)}.round-source>span:last-child{grid-column:1}}
</style>
